import React, { useEffect, useState } from 'react';
import { MenuButton } from './P5UI';
import SettingsModal from './SettingsModal';
import { Settings } from '../types';
import { TRANSLATIONS } from '../constants';

interface MainMenuProps {
    onStart: () => void;
    settings: Settings;
    onUpdateSettings: (s: Settings) => void;
}

const MainMenu: React.FC<MainMenuProps> = ({ onStart, settings, onUpdateSettings }) => {
    const [mounted, setMounted] = useState(false);
    const [showSettings, setShowSettings] = useState(false);
    const t = TRANSLATIONS[settings.language];

    useEffect(() => {
        setMounted(true);
    }, []);

    return (
        <div className="absolute inset-0 z-50 flex overflow-hidden bg-[#050510]">
            {/* Ambient Background Grid & Glows */}
            <div className="absolute inset-0 bg-p5-pattern opacity-20 pointer-events-none" style={{ backgroundSize: '60px 60px' }} />
            <div className="absolute top-[-10%] right-[-10%] w-[50%] h-[50%] bg-p5-purple/20 blur-[120px] rounded-full" />
            <div className="absolute bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-p5-blue/20 blur-[120px] rounded-full" />

            {/* Diagonal Divider with Neon Glow */}
            <div className="absolute top-0 bottom-0 left-[40%] w-[200%] bg-black transform -skew-x-12 origin-top-left z-0 border-l-4 border-p5-cyan shadow-neon-cyan hidden lg:block" />

            {/* Left Content: The Brand Identity */}
            <div className={`
                absolute inset-0 lg:static lg:w-[45%] lg:flex-none
                flex flex-col items-center justify-center 
                transition-all duration-1000 z-10
                ${mounted ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-20'}
            `}>
                <div className="relative p-8 text-center flex flex-col items-center">
                    {/* The "Neon Blocks" Boxed Logo Style from gameplay */}
                    <div className="bg-p5-dark text-white font-p5-display text-7xl lg:text-9xl px-8 py-4 border-8 border-white shadow-neon-pink relative z-10 transform -rotate-3 animate-float-glitch">
                        NEON<span className="text-p5-red">BLOCKS</span>
                        {/* Inner detail lines */}
                        <div className="absolute top-2 left-2 right-2 h-[2px] bg-white/20" />
                    </div>

                    <div className="mt-12 transform rotate-2">
                         <div className="bg-p5-cyan text-black px-6 py-2 tracking-[0.4em] font-black text-xl animate-pulse border-2 border-white shadow-hard-black transform -skew-x-12">
                             METAVERSE // PROTOCOL
                         </div>
                    </div>

                    <div className="mt-8 flex gap-4">
                        <div className="w-12 h-2 bg-p5-purple transform -skew-x-12" />
                        <div className="w-24 h-2 bg-white transform -skew-x-12" />
                        <div className="w-12 h-2 bg-p5-cyan transform -skew-x-12" />
                    </div>
                </div>
            </div>

            {/* Right Content: The Menu */}
            <div className={`
                absolute bottom-20 left-0 right-0 lg:static lg:w-[55%] lg:flex-none
                flex flex-col justify-center items-center lg:items-start pl-0 lg:pl-32
                z-20
                transition-all duration-1000 delay-300
                ${mounted ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-20'}
            `}>
                <div className="w-full max-w-md relative z-10 p-4 lg:p-0">
                     <div className="flex flex-col gap-8 w-full transform rotate-1">
                        <div className="text-white/80 font-p5-ui text-sm tracking-widest mb-4 border-b-2 border-p5-cyan/50 pb-2 flex justify-between items-end">
                             <div className="flex flex-col">
                                <span className="text-[10px] opacity-50 uppercase">User Identity</span>
                                <span className="text-p5-cyan font-bold">PHANTOM_THIEF.OS</span>
                             </div>
                             <span className="bg-p5-purple text-white px-3 py-1 text-xs font-bold animate-pulse">LIVE FEED</span>
                        </div>

                        <MenuButton label={t.start} onClick={onStart} primary />
                        <MenuButton label={t.options} onClick={() => setShowSettings(true)} active={true} />
                        <MenuButton label={t.records} onClick={() => {}} active={false} />

                        <div className="mt-4 flex justify-between text-p5-cyan font-p5-ui text-[10px] tracking-[0.2em] bg-white/5 backdrop-blur-sm p-3 border-l-4 border-p5-purple">
                            <span>REVISION // 1.0.5</span>
                            <span>ENCRYPTED_LINK_SECURE</span>
                        </div>
                     </div>
                </div>

                {/* Floating Card - Cyan Style */}
                <div className="hidden lg:block absolute right-32 top-1/4 w-48 h-64 bg-black border-4 border-white animate-card-float shadow-neon-blue transform rotate-12 z-0">
                    <div className="absolute inset-0 bg-p5-pattern opacity-20" />
                    <div className="absolute inset-4 border-2 border-p5-cyan flex items-center justify-center overflow-hidden">
                         <div className="text-p5-cyan font-p5-display text-6xl opacity-20 transform -rotate-45">NB</div>
                    </div>
                </div>
            </div>

            {/* Bottom Ticker - Cyan/Black instead of Yellow */}
            <div className="absolute bottom-0 left-0 right-0 h-12 bg-p5-cyan text-black font-p5-display text-2xl tracking-[0.1em] flex items-center overflow-hidden border-t-4 border-white z-40 transform -skew-x-6 origin-bottom-left scale-110 shadow-[0_-10px_30px_rgba(5,217,232,0.3)]">
                <div className="whitespace-nowrap animate-ticker pl-full">
                    {t.ticker} {t.ticker}
                </div>
            </div>

            <SettingsModal 
                isOpen={showSettings} 
                onClose={() => setShowSettings(false)}
                settings={settings}
                onUpdate={onUpdateSettings}
            />
        </div>
    );
};

export default MainMenu;

import React from 'react';
import { TetrominoType } from '../types';
import { TETROMINOES } from '../constants';

export const PhantomContainer: React.FC<{ 
    children: React.ReactNode; 
    className?: string; 
    rotated?: boolean;
    black?: boolean;
    glass?: boolean;
}> = ({ children, className = '', rotated = true, black = false, glass = false }) => {
    return (
        <div className={`relative group ${className}`}>
            {/* Background Shape - Jagged P5 Style with Neon Blocks Palette */}
            <div className={`
                absolute inset-0 clip-jagged
                ${glass ? 'bg-black/85 backdrop-blur-xl border border-white/30' : 
                  black ? 'bg-black border-2 border-p5-cyan' : 
                  'bg-white border-4 border-black'} 
                ${glass ? 'shadow-neon-cyan' : 'shadow-hard-black'}
                transition-all duration-300
                ${rotated ? 'transform -rotate-1' : ''}
            `} />

            {/* Content */}
            <div className="relative z-10 p-6">
                {children}
            </div>
        </div>
    );
};

export const ScoreBoard: React.FC<{ score: number; level: number; lines: number }> = ({ score, level, lines }) => {
    return (
        <div className="relative mb-8 w-full max-w-[320px]">
            <div className="absolute -top-6 -left-2 z-30 transform -rotate-3">
                <div className="bg-p5-cyan text-black px-4 py-1 font-p5-display text-2xl border-2 border-white shadow-hard-black skew-x-[-10deg]">
                    SYSTEM_STATS
                </div>
            </div>

            <PhantomContainer glass rotated={false} className="w-full mt-4">
                <div className="flex flex-col font-p5-ui text-white space-y-4">
                    <div className="flex flex-col border-b border-white/20 pb-4">
                         <span className="text-xl text-p5-cyan uppercase font-bold tracking-[0.2em] mb-1 drop-shadow-md">Score</span>
                         <span className="text-6xl font-p5-display tracking-tight leading-none text-white drop-shadow-[3px_3px_0_#ff2a6d]">
                            {score.toLocaleString()}
                         </span>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="flex flex-col">
                            <span className="text-p5-purple uppercase tracking-widest text-xs font-bold opacity-80">Security</span>
                            <span className="text-4xl font-p5-display text-p5-yellow drop-shadow-md">{level}</span>
                        </div>
                        <div className="flex flex-col text-right">
                            <span className="text-p5-blue uppercase tracking-widest text-xs font-bold opacity-80">Cleared</span>
                            <span className="text-4xl font-p5-display text-white drop-shadow-md">{lines}</span>
                        </div>
                    </div>
                </div>
