};

export const NextPiece: React.FC<{ type: TetrominoType }> = ({ type }) => {
    const piece = TETROMINOES[type];

    return (
        <div className="relative w-48 h-48 mb-8 transform rotate-2">
            <div className="absolute -top-4 -right-4 z-30 bg-black text-p5-cyan px-4 py-1 font-p5-display text-xl border-2 border-p5-cyan shadow-neon-cyan whitespace-nowrap transform skew-x-12">
                INCOMING
            </div>

            <div className="absolute inset-0 bg-black/80 border-4 border-p5-blue clip-jagged shadow-neon-blue flex items-center justify-center overflow-hidden">
                <div className="absolute inset-0 bg-p5-pattern opacity-10"></div>
                <div className="relative z-10 grid gap-1 transform scale-125" style={{ 
                     gridTemplateColumns: `repeat(${piece.shape[0].length}, 1fr)`,
                 }}>
                    {piece.shape.map((row, y) => 
                        row.map((cell, x) => (
                            <div key={`${x}-${y}`} className={`w-6 h-6 ${cell ? '' : 'transparent'}`} 
                                 style={{ 
                                     backgroundColor: cell ? piece.color : 'transparent',
                                     border: cell ? '2px solid rgba(255,255,255,0.8)' : 'none',
                                     boxShadow: cell ? `0 0 15px ${piece.color}` : 'none'
                                }}>
                            </div>
                        ))
                    )}
                 </div>
            </div>
        </div>
    );
};

export const MenuButton: React.FC<{ onClick: () => void; label: string; active?: boolean; primary?: boolean }> = ({ onClick, label, active = true, primary = false }) => {
    return (
        <button 
            onClick={onClick}
            disabled={!active}
            className={`
                relative group w-full py-5 px-8 
                font-p5-display text-3xl tracking-widest uppercase
                transition-all duration-100 active:scale-95
                ${active ? 'cursor-pointer' : 'opacity-50 cursor-not-allowed'}
            `}
        >
            {/* Background */}
            <div className={`
                absolute inset-0 transform -skew-x-12 border-2 clip-jagged
                ${primary ? 'bg-white border-black' : 'bg-p5-dark border-p5-cyan'}
                shadow-hard-black group-hover:shadow-neon-pink transition-all duration-300
                group-hover:scale-105 group-hover:-rotate-1
            `} />

            {/* Text */}
            <span className={`
                relative z-10 block transform skew-x-12
                ${primary ? 'text-black' : 'text-white'}
                group-hover:text-p5-red transition-colors duration-200
                drop-shadow-sm
            `}>
                {label}
            </span>
        </button>
    );
};

export const Modal: React.FC<{ title: string; children: React.ReactNode; isOpen: boolean }> = ({ title, children, isOpen }) => {
    if (!isOpen) return null;
    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center scanlines">
            <div className="absolute inset-0 bg-black/90 backdrop-blur-xl animate-in fade-in duration-300" />

            <div className="relative z-10 animate-slam-in max-w-lg w-full p-4">
                <div className="absolute -inset-1 bg-gradient-to-r from-p5-cyan to-p5-blue clip-jagged shadow-neon-cyan transform rotate-1" />

                <div className="relative bg-black p-12 text-center clip-jagged border-2 border-white/20 transform -rotate-1">
                     <h2 className="font-p5-display text-7xl text-white mb-6 text-glitch tracking-tighter drop-shadow-[4px_4px_0_#ff2a6d]" data-text={title}>{title}</h2>
                     <div className="w-full h-2 bg-p5-cyan transform -skew-x-12 mb-8" />

                     <div className="font-p5-ui text-xl text-gray-200 mb-8 font-bold">
                        {children}
                     </div>
                </div>
            </div>
        </div>
    );
}

import React, { useEffect, useState } from 'react';

interface IntroSequenceProps {
    onComplete: () => void;
}

const IntroSequence: React.FC<IntroSequenceProps> = ({ onComplete }) => {
    const [phase, setPhase] = useState<'start' | 'reveal' | 'exit'>('start');

    useEffect(() => {
        const startDelay = 200;
        const holdTime = 2200;
        const exitTime = 500;

        const t1 = setTimeout(() => setPhase('reveal'), startDelay);
        const t2 = setTimeout(() => setPhase('exit'), startDelay + holdTime);
        const t3 = setTimeout(onComplete, startDelay + holdTime + exitTime);

        return () => {
            clearTimeout(t1);
            clearTimeout(t2);
            clearTimeout(t3);
        };
    }, [onComplete]);

    return (
        <div className={`
            fixed inset-0 z-[200] bg-[#02020a] flex items-center justify-center
            transition-opacity duration-700
            ${phase === 'exit' ? 'opacity-0 pointer-events-none' : 'opacity-100'}
        `}>
            <div className="relative p-12">
                {/* Horizontal Scanline */}
                <div className={`absolute top-1/2 left-0 h-[2px] bg-p5-cyan transition-all duration-1000 ease-out transform -translate-y-1/2 shadow-neon-cyan ${phase === 'reveal' ? 'w-full opacity-100' : 'w-0 opacity-0'}`} />

                <div className={`flex flex-col items-center transform transition-all duration-700 ${phase === 'reveal' ? 'scale-100 opacity-100' : 'scale-75 opacity-0'}`}>

                    <span className="font-p5-ui text-p5-cyan tracking-[0.6em] text-[10px] mb-6 uppercase font-black opacity-80">
                        Initializing Metaverse Connection
                    </span>

                    <div className="relative bg-black border-4 border-white px-10 py-6 shadow-neon-pink transform -rotate-2">
                        <h1 className="font-p5-display text-5xl md:text-8xl text-white tracking-tighter uppercase leading-none">
                            NEON
                        </h1>
                        <h1 className="font-p5-display text-5xl md:text-8xl text-p5-red tracking-tighter uppercase mt-[-10px] leading-none">
                            BLOCKS
                        </h1>
                    </div>

                    <div className="mt-8 flex gap-3">
                        <div className="w-12 h-1 bg-p5-cyan animate-pulse" />
                        <div className="w-4 h-1 bg-white animate-pulse delay-75" />
                        <div className="w-4 h-1 bg-p5-purple animate-pulse delay-150" />
                    </div>
                </div>
            </div>

            {/* Heavy Scanlines Overlay */}
            <div className="absolute inset-0 pointer-events-none scanlines opacity-60" />
        </div>
    );
};

export default IntroSequence;

import React, { useState, useCallback, useEffect } from 'react';
import { useTetris } from './hooks/useTetris';
import Board from './components/Board';
import { ScoreBoard, NextPiece, MenuButton, Modal } from './components/P5UI';
import P5Background from './components/P5Background';
import MainMenu from './components/MainMenu';
import TransitionOverlay, { TransitionStage } from './components/TransitionOverlay';
import IntroSequence from './components/IntroSequence';
import PauseMenu from './components/PauseMenu';
import { Settings } from './types';
import { TRANSLATIONS } from './constants';
import { Volume2, VolumeX, Pause, Play } from 'lucide-react';

const App: React.FC = () => {
  const {
    grid,
    piece,
    score,
    lines,
    level,
    gameOver,
    isPaused,
    isPlaying,
    isShaking,
    nextPieceType,
    popups,
    startGame,
    quitGame,
    setIsPaused
  } = useTetris();

  const [settings, setSettings] = useState<Settings>({
      sound: true,
      shake: true,
      language: 'en'
  });

  const t = TRANSLATIONS[settings.language];
  const [transitionStage, setTransitionStage] = useState<TransitionStage>('idle');
  const [showGame, setShowGame] = useState(false);
  const [introComplete, setIntroComplete] = useState(false);

  const handleStart = useCallback(() => {
      setTransitionStage('in');
      setTimeout(() => {
          setShowGame(true);
          startGame();
          setTransitionStage('out');
          setTimeout(() => setTransitionStage('idle'), 700); 
      }, 1200); 
  }, [startGame]);

  const handleQuit = useCallback(() => {
      setTransitionStage('in');
      setTimeout(() => {
        quitGame();
        setShowGame(false);
        setTransitionStage('out');
        setTimeout(() => setTransitionStage('idle'), 700);
      }, 1200);
  }, [quitGame]);

  return (
    <div className="relative min-h-screen w-full overflow-hidden font-p5-ui select-none bg-[#050510]">
      <P5Background />

      {!introComplete && <IntroSequence onComplete={() => setIntroComplete(true)} />}

      <TransitionOverlay stage={transitionStage} />

      <div className={`transition-opacity duration-1000 ${introComplete ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
        {!showGame ? (
            <MainMenu 
                onStart={handleStart} 
                settings={settings}
                onUpdateSettings={setSettings}
            />
        ) : (
            <div className="relative z-10 w-full h-screen grid grid-cols-1 lg:grid-cols-[1fr_auto_1fr] gap-0 items-center justify-items-center perspective-1000">

              {/* Left Column: Stats */}
              <div className={`
                    hidden lg:flex flex-col items-end justify-center h-full w-full pr-16 space-y-16 relative z-20 
                    transition-all duration-500 ease-out-expo origin-right
                    ${isPaused && !gameOver ? '-translate-x-[100vw] rotate-[-5deg] opacity-0' : 'translate-x-0 rotate-0 opacity-100 animate-slam-in'}
              `}>
                  <div className="relative group cursor-default transform scale-75 origin-right animate-float-glitch">
                      <div className="bg-p5-dark text-white font-p5-display text-6xl px-6 py-3 border-4 border-white shadow-neon-pink relative z-10">
                          NEON<span className="text-p5-red">BLOCKS</span>
                      </div>
                  </div>
                  <ScoreBoard score={score} level={level} lines={lines} />
              </div>

              {/* Center: The Board */}
              <div className={`
                    relative flex items-center justify-center h-full py-4 lg:py-8 z-10 
                    transition-all duration-500 ease-out-expo
                    ${isPaused && !gameOver ? 'scale-75 opacity-20 blur-sm brightness-50 translate-y-10' : 'scale-100 opacity-100 animate-slam-in'}
              `}>
                  <Board 
                    grid={grid} 
                    piece={piece} 
                    isShaking={isShaking} 
                    popups={popups} 
                    shakeEnabled={settings.shake}
                  />
              </div>

              {/* Right Column: Next & Controls */}
              <div className={`
                    hidden lg:flex flex-col items-start justify-center h-full w-full pl-16 space-y-12 relative z-20 
                    transition-all duration-500 ease-out-expo origin-left
                    ${isPaused && !gameOver ? 'translate-x-[100vw] rotate-[5deg] opacity-0' : 'translate-x-0 rotate-0 opacity-100 animate-slam-in'}
              `}>
                  <NextPiece type={nextPieceType} />
                  <div className="flex flex-col gap-6 w-full max-w-[280px]">
                      <MenuButton label={isPaused ? t.resume : t.paused} onClick={() => setIsPaused()} active={!gameOver} primary />
                      <div className="flex gap-4 w-full">
                            <button onClick={() => setSettings({...settings, sound: !settings.sound})} className="flex-1 bg-p5-dark text-white p-4 border-2 border-p5-cyan hover:bg-p5-cyan hover:text-black transition-all transform hover:rotate-3 shadow-neon-cyan flex items-center justify-center">
                              {settings.sound ? <Volume2 size={28} /> : <VolumeX size={28} />}
                            </button>
                            <button onClick={handleQuit} className="flex-1 bg-p5-dark text-p5-red p-4 border-2 border-p5-red hover:bg-p5-red hover:text-white transition-all transform hover:-rotate-3 shadow-neon-pink font-bold flex items-center justify-center uppercase tracking-widest">{t.quit}</button>
                      </div>
                  </div>
              </div>

              {isPaused && !gameOver && (
                  <div className="absolute inset-0 z-50 flex items-center justify-center">
                    <PauseMenu onResume={() => setIsPaused()} onQuit={handleQuit} />
                  </div>
              )}
            </div>
        )}
      </div>

      <Modal title={t.gameOver} isOpen={gameOver}>
          <div className="flex flex-col gap-8 items-center">
              <div className="text-4xl font-black bg-white text-black px-6 py-2 transform -skew-x-12 inline-block border-2 border-p5-dark shadow-hard-black">
                {t.score}: {score.toLocaleString()}
              </div>
              <div className="w-full h-px bg-white/30" />
              <div className="flex flex-col w-full gap-4">
                  <MenuButton label={t.retry} onClick={handleStart} primary />
                  <button onClick={handleQuit} className="text-white/70 hover:text-white underline underline-offset-4 decoration-p5-red decoration-2 uppercase tracking-widest font-bold">
                      {t.back}
                  </button>
              </div>
          </div>
      </Modal>
    </div>
  );
};

export default App;

