import React from 'react';
import { TRANSLATIONS } from '../constants';
import { Language } from '../types';

export type TransitionStage = 'idle' | 'in' | 'out';

interface TransitionOverlayProps {
  stage: TransitionStage;
  language: Language;
}

const TransitionOverlay: React.FC<TransitionOverlayProps> = ({ stage, language }) => {
  if (stage === 'idle') return null;
  const t = TRANSLATIONS[language];

  return (
    <div className="fixed inset-0 z-[150] pointer-events-none overflow-hidden">
      {/* Bar 1: Deep Blue Base */}
      <div 
        className={`absolute inset-0 bg-p5-blue transform transition-transform duration-600 ease-out-expo z-30`}
        style={{ 
            clipPath: 'polygon(0 0, 100% 0, 100% 100%, 0% 100%)',
            transform: stage === 'in' ? 'translateX(0)' : 'translateX(100%)',
            transitionDelay: stage === 'in' ? '0ms' : '300ms'
        }}
      />

      {/* Bar 2: Purple Slash */}
      <div 
        className={`absolute inset-0 bg-p5-purple transform transition-transform duration-600 ease-out-expo z-40`}
        style={{ 
            clipPath: 'polygon(0 0, 120% 0, 80% 100%, -20% 100%)',
            transform: stage === 'in' ? 'translateX(0)' : 'translateX(130%)',
            transitionDelay: stage === 'in' ? '100ms' : '150ms'
        }}
      />

      {/* Bar 3: Pink Slash (Top) */}
      <div 
        className={`absolute inset-0 bg-p5-red transform transition-transform duration-600 ease-out-expo z-50`}
        style={{ 
            clipPath: 'polygon(0 0, 150% 0, 100% 100%, -50% 100%)',
            transform: stage === 'in' ? 'translateX(0)' : 'translateX(160%)',
            transitionDelay: stage === 'in' ? '200ms' : '0ms'
        }}
      >
          {/* High Impact Loading Text */}
          <div className="absolute bottom-20 right-20 flex flex-col items-end">
              <div className="flex gap-2 mb-2">
                 {t.loading.split('').map((char, i) => (
                    <span 
                        key={i} 
                        className="font-p5-display text-7xl text-white inline-block opacity-0"
                        style={{ 
                            animation: stage === 'in' ? 'letterReveal 0.4s cubic-bezier(0.16, 1, 0.3, 1) both' : 'none',
                            animationDelay: `${0.4 + (i * 0.03)}s`
                        }}
                    >
                        {char}
                    </span>
                 ))}
              </div>
              <div className={`h-1 bg-white transition-all duration-1000 ease-out-expo ${stage === 'in' ? 'w-full opacity-100' : 'w-0 opacity-0'}`} />
          </div>
      </div>
    </div>
  );
};

export default TransitionOverlay;

import React, { useState, useCallback, useEffect } from 'react';
import { useTetris } from './hooks/useTetris';
import Board from './components/Board';
import { ScoreBoard, NextPiece, MenuButton, Modal } from './components/P5UI';
import P5Background from './components/P5Background';
import MainMenu from './components/MainMenu';
import TransitionOverlay, { TransitionStage } from './components/TransitionOverlay';
import IntroSequence from './components/IntroSequence';
import PauseMenu from './components/PauseMenu';
import { Settings } from './types';
import { TRANSLATIONS } from './constants';
import { Volume2, VolumeX } from 'lucide-react';

const App: React.FC = () => {
  const {
    grid,
    piece,
    score,
    lines,
    level,
    gameOver,
    isPaused,
    isPlaying,
    isShaking,
    nextPieceType,
    popups,
    startGame,
    quitGame,
    setIsPaused
  } = useTetris();

  const [settings, setSettings] = useState<Settings>({
      sound: true,
      shake: true,
      language: 'en'
  });

  const t = TRANSLATIONS[settings.language];
  const [transitionStage, setTransitionStage] = useState<TransitionStage>('idle');
  const [showGame, setShowGame] = useState(false);
  const [isMenuExiting, setIsMenuExiting] = useState(false);
  const [introComplete, setIntroComplete] = useState(false);

  const handleStart = useCallback(() => {
      setIsMenuExiting(true); // Trigger menu slide-out
      setTimeout(() => {
          setTransitionStage('in'); // Slash animation covers
          setTimeout(() => {
              setShowGame(true);
              startGame();
              setTransitionStage('out'); // Slash animation clears
              setTimeout(() => {
                  setTransitionStage('idle');
                  setIsMenuExiting(false);
              }, 700); 
          }, 1000); 
      }, 500); // Wait for menu exit animation to start
  }, [startGame]);

  const handleQuit = useCallback(() => {
      setTransitionStage('in');
      setTimeout(() => {
        quitGame();
        setShowGame(false);
        setTransitionStage('out');
        setTimeout(() => setTransitionStage('idle'), 700);
      }, 1000);
  }, [quitGame]);

  return (
    <div className="relative min-h-screen w-full overflow-hidden font-p5-ui select-none bg-[#050510]">
      <P5Background />

      {!introComplete && <IntroSequence onComplete={() => setIntroComplete(true)} />}

      <TransitionOverlay stage={transitionStage} language={settings.language} />

      <div className={`transition-opacity duration-1000 ${introComplete ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
        {!showGame ? (
            <MainMenu 
                onStart={handleStart} 
                settings={settings}
                onUpdateSettings={setSettings}
                isExiting={isMenuExiting}
            />
        ) : (
            <div className="relative z-10 w-full h-screen grid grid-cols-1 lg:grid-cols-[1fr_auto_1fr] gap-0 items-center justify-items-center perspective-1000">

              {/* Left Column: Stats */}
              <div className={`
                    hidden lg:flex flex-col items-end justify-center h-full w-full pr-16 space-y-16 relative z-20 
                    transition-all duration-700 ease-out-expo origin-right
                    ${isPaused && !gameOver ? '-translate-x-[100vw] rotate-[-5deg] opacity-0' : 'translate-x-0 rotate-0 opacity-100 animate-slam-in'}
              `}>
                  <div className="relative group cursor-default transform scale-75 origin-right animate-float-glitch">
                      <div className="bg-p5-dark text-white font-p5-display text-6xl px-6 py-3 border-4 border-white shadow-neon-pink relative z-10">
                          NEON<span className="text-p5-red">BLOCKS</span>
                      </div>
                  </div>
                  <ScoreBoard score={score} level={level} lines={lines} />
              </div>

              {/* Center: The Board */}
              <div className={`
                    relative flex items-center justify-center h-full py-4 lg:py-8 z-10 
                    transition-all duration-700 ease-out-expo
                    ${isPaused && !gameOver ? 'scale-75 opacity-20 blur-sm brightness-50 translate-y-10' : 'scale-100 opacity-100 animate-slam-in'}
              `}>
                  <Board 
                    grid={grid} 
                    piece={piece} 
                    isShaking={isShaking} 
                    popups={popups} 
                    shakeEnabled={settings.shake}
                  />
              </div>

              {/* Right Column: Next & Controls */}
              <div className={`
                    hidden lg:flex flex-col items-start justify-center h-full w-full pl-16 space-y-12 relative z-20 
                    transition-all duration-700 ease-out-expo origin-left
                    ${isPaused && !gameOver ? 'translate-x-[100vw] rotate-[5deg] opacity-0' : 'translate-x-0 rotate-0 opacity-100 animate-slam-in'}
              `}>
                  <NextPiece type={nextPieceType} />
                  <div className="flex flex-col gap-6 w-full max-w-[280px]">
                      <MenuButton label={isPaused ? t.resume : t.paused} onClick={() => setIsPaused()} active={!gameOver} primary />
                      <div className="flex gap-4 w-full">
                            <button onClick={() => setSettings({...settings, sound: !settings.sound})} className="flex-1 bg-p5-dark text-white p-4 border-2 border-p5-cyan hover:bg-p5-cyan hover:text-black transition-all transform hover:rotate-3 shadow-neon-cyan flex items-center justify-center">
                              {settings.sound ? <Volume2 size={28} /> : <VolumeX size={28} />}
                            </button>
                            <button onClick={handleQuit} className="flex-1 bg-p5-dark text-p5-red p-4 border-2 border-p5-red hover:bg-p5-red hover:text-white transition-all transform hover:-rotate-3 shadow-neon-pink font-bold flex items-center justify-center uppercase tracking-widest">{t.quit}</button>
                      </div>
                  </div>
              </div>

              {isPaused && !gameOver && (
                  <div className="absolute inset-0 z-50 flex items-center justify-center">
                    <PauseMenu onResume={() => setIsPaused()} onQuit={handleQuit} />
                  </div>
              )}
            </div>
        )}
      </div>

      <Modal title={t.gameOver} isOpen={gameOver}>
          <div className="flex flex-col gap-8 items-center">
              <div className="text-4xl font-black bg-white text-black px-6 py-2 transform -skew-x-12 inline-block border-2 border-p5-dark shadow-hard-black">
                {t.score}: {score.toLocaleString()}
              </div>
              <div className="w-full h-px bg-white/30" />
              <div className="flex flex-col w-full gap-4">
                  <MenuButton label={t.retry} onClick={handleStart} primary />
                  <button onClick={handleQuit} className="text-white/70 hover:text-white underline underline-offset-4 decoration-p5-red decoration-2 uppercase tracking-widest font-bold">
                      {t.back}
                  </button>
              </div>
          </div>
      </Modal>
    </div>
  );
};

export default App;

export enum TetrominoType {
  I = 'I',
  J = 'J',
  L = 'L',
  O = 'O',
  S = 'S',
  T = 'T',
  Z = 'Z',
}

export type TetrominoShape = number[][];

export interface Tetromino {
  type: TetrominoType;
  shape: TetrominoShape;
  color: string; // Tailwind class or hex
}

export type CellValue = TetrominoType | null;

export type BoardGrid = {
  value: CellValue;
  locked: boolean;
  color?: string;
  isGhost?: boolean;
}[][];

export interface Popup {
  id: number;
  text: string;
  x: number; // grid coords approx
  y: number;
  color: string;
}

export interface HighScore {
  score: number;
  date: string;
}

export interface GameState {
  grid: BoardGrid;
  currentPiece: {
    type: TetrominoType;
    shape: TetrominoShape;
    x: number;
    y: number;
    color: string;
  } | null;
  score: number;
  level: number;
  lines: number;
  gameOver: boolean;
  isPaused: boolean;
  nextPiece: TetrominoType;
}

export type Language = 'en' | 'it';

export interface Settings {
  sound: boolean;
  shake: boolean;
  language: Language;
}

export const BOARD_WIDTH = 10;
export const BOARD_HEIGHT = 20;

import { useState, useEffect, useCallback, useRef } from 'react';
import { BoardGrid, TetrominoType, BOARD_WIDTH, BOARD_HEIGHT, Popup, HighScore } from '../types';
import { TETROMINOES, INITIAL_SPEED, SPEED_DECREMENT, MIN_SPEED, STORAGE_KEY } from '../constants';

const createEmptyGrid = (): BoardGrid =>
  Array.from({ length: BOARD_HEIGHT }, () =>
    Array.from({ length: BOARD_WIDTH }, () => ({ value: null, locked: false }))
  );

const getRandomTetromino = () => {
  const types = Object.values(TetrominoType);
  const type = types[Math.floor(Math.random() * types.length)];
  return TETROMINOES[type];
};

export const useTetris = () => {
  const [grid, setGrid] = useState<BoardGrid>(createEmptyGrid());
  const [score, setScore] = useState(0);
  const [lines, setLines] = useState(0);
  const [level, setLevel] = useState(1);
  const [gameOver, setGameOver] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [nextPieceType, setNextPieceType] = useState<TetrominoType>(getRandomTetromino().type);
  const [piece, setPiece] = useState<{
    type: TetrominoType;
    shape: number[][];
    x: number;
    y: number;
    color: string;
  } | null>(null);

  const [isShaking, setIsShaking] = useState(false);
  const [popups, setPopups] = useState<Popup[]>([]);
  const [highScores, setHighScores] = useState<HighScore[]>([]);
  const [speedRatio, setSpeedRatio] = useState(0); // 0 to 1

  const comboRef = useRef(0);

  const stateRef = useRef({
    grid: createEmptyGrid(),
    piece: null as { type: TetrominoType; shape: number[][]; x: number; y: number; color: string } | null,
    nextPieceType: getRandomTetromino().type,
    score: 0,
    lines: 0,
    level: 1,
    gameOver: false,
    isPaused: false,
    isPlaying: false,
  });

  // Load High Scores
  useEffect(() => {
    try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
            setHighScores(JSON.parse(saved));
        }
    } catch (e) {
        console.error("Failed to load high scores", e);
    }
  }, []);

  useEffect(() => {
    stateRef.current.nextPieceType = nextPieceType;
  }, []);

  const requestRef = useRef<number>(0);
  const lastTimeRef = useRef<number>(0);
  const dropCounterRef = useRef<number>(0);

  const triggerShake = useCallback(() => {
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 300);
  }, []);

  const addPopup = useCallback((text: string, x: number, y: number, color: string) => {
      const id = Date.now() + Math.random();
      setPopups(prev => [...prev, { id, text, x, y, color }]);
      setTimeout(() => {
          setPopups(prev => prev.filter(p => p.id !== id));
      }, 1500);
  }, []);

  const saveHighScore = useCallback((finalScore: number) => {
      if (finalScore === 0) return;

      setHighScores(prev => {
          const newEntry: HighScore = { score: finalScore, date: new Date().toISOString() };
          const newScores = [...prev, newEntry]
            .sort((a, b) => b.score - a.score)
            .slice(0, 5);

          localStorage.setItem(STORAGE_KEY, JSON.stringify(newScores));
          return newScores;
      });
  }, []);

  const checkCollision = (shape: number[][], x: number, y: number, currentGrid: BoardGrid) => {
    for (let r = 0; r < shape.length; r++) {
      for (let c = 0; c < shape[r].length; c++) {
        if (shape[r][c] !== 0) {
          const newX = x + c;
          const newY = y + r;

          if (
            newX < 0 ||
            newX >= BOARD_WIDTH ||
            newY >= BOARD_HEIGHT ||
            (newY >= 0 && currentGrid[newY][newX].locked)
          ) {
            return true;
          }
        }
      }
    }
    return false;
  };

  const spawnPiece = useCallback(() => {
    const currentState = stateRef.current;
    if (currentState.gameOver || !currentState.isPlaying) return;

    const type = currentState.nextPieceType;
    const newNext = getRandomTetromino().type;

    currentState.nextPieceType = newNext;
    setNextPieceType(newNext);

    const newPieceTemplate = TETROMINOES[type];
    const initialX = Math.floor(BOARD_WIDTH / 2) - Math.floor(newPieceTemplate.shape[0].length / 2);

    if (checkCollision(newPieceTemplate.shape, initialX, 0, currentState.grid)) {
        currentState.gameOver = true;
        setGameOver(true);
        saveHighScore(currentState.score);
        return;
    }

    const newPiece = {
        type: newPieceTemplate.type,
        shape: newPieceTemplate.shape,
        x: initialX,
        y: 0,
        color: newPieceTemplate.color,
    };

    currentState.piece = newPiece;
    setPiece(newPiece);
  }, [saveHighScore]);

  const lockPiece = useCallback(() => {
    const s = stateRef.current;
    if (!s.piece) return;

    const newGrid = s.grid.map(row => row.map(cell => ({ ...cell })));

    s.piece.shape.forEach((row, r) => {
      row.forEach((value, c) => {
        if (value !== 0) {
          const y = s.piece!.y + r;
          const x = s.piece!.x + c;
          if (y >= 0 && y < BOARD_HEIGHT) {
            newGrid[y][x] = { value: s.piece!.type, locked: true, color: s.piece!.color };
          }
        }
      });
    });

    let linesCleared = 0;
    const finalGrid = newGrid.reduce((acc, row) => {
      if (row.every((cell) => cell.locked)) {
        linesCleared++;
        acc.unshift(Array.from({ length: BOARD_WIDTH }, () => ({ value: null, locked: false })));
      } else {
        acc.push(row);
      }
      return acc;
    }, [] as BoardGrid);

    s.grid = finalGrid;

    // Popup and Combo Logic
    if (linesCleared > 0) {
        s.score += linesCleared * 100 * s.level * (comboRef.current + 1);
        s.lines += linesCleared;

        comboRef.current += 1; // Increment combo

        // Popup Text
        const popupX = s.piece.x + 1;
        const popupY = s.piece.y;

        if (linesCleared === 4) {
             addPopup("TETRIS!!", popupX, popupY, '#ff2a6d');
             triggerShake();
        } else if (linesCleared === 3) {
             addPopup("SUPER!", popupX, popupY, '#d300c5');
        } else if (linesCleared === 2) {
             addPopup("GREAT", popupX, popupY, '#05d9e8');
        } else {
             addPopup("GOOD", popupX, popupY, '#ffffff');
        }

        if (comboRef.current > 1) {
            setTimeout(() => {
                addPopup(`COMBO x${comboRef.current}`, popupX, popupY - 2, '#fcee0a');
            }, 300);
        }

        // Level up every 10 lines
        if (Math.floor(s.lines / 10) > Math.floor((s.lines - linesCleared) / 10)) {
            s.level += 1;
            // Visual feedback for level up could go here
            addPopup("LEVEL UP!", BOARD_WIDTH / 2, 5, '#05d9e8');
        }
        setScore(s.score);
        setLines(s.lines);
        setLevel(s.level);

        triggerShake(); 
    } else {
        comboRef.current = 0;
    }

    setGrid(finalGrid);
    s.piece = null;
    spawnPiece();
  }, [spawnPiece, triggerShake, addPopup]);

  const move = useCallback((dirX: number, dirY: number) => {
    const s = stateRef.current;
    if (!s.piece || s.gameOver || s.isPaused || !s.isPlaying) return;

    if (!checkCollision(s.piece.shape, s.piece.x + dirX, s.piece.y + dirY, s.grid)) {
      s.piece = { ...s.piece, x: s.piece.x + dirX, y: s.piece.y + dirY };
      setPiece(s.piece); 
      return true;
    } else if (dirY > 0) {
      lockPiece();
      return false;
    }
    return false;
  }, [lockPiece]);

  const rotate = useCallback((direction: 1 | -1 = 1) => {
    const s = stateRef.current;
    if (!s.piece || s.gameOver || s.isPaused || !s.isPlaying) return;

    const shape = s.piece.shape;
    const rows = shape.length;
    const cols = shape[0].length;
    let rotatedShape: number[][] = Array.from({length: cols}, () => Array(rows).fill(0));

    if (direction === 1) {
        for(let r = 0; r < rows; r++) {
            for(let c = 0; c < cols; c++) {
                rotatedShape[c][rows - 1 - r] = shape[r][c];
            }
        }
    } else {
        for(let r = 0; r < rows; r++) {
            for(let c = 0; c < cols; c++) {
                rotatedShape[cols - 1 - c][r] = shape[r][c];
            }
        }
    }

    let offset = 0;
    if (checkCollision(rotatedShape, s.piece.x, s.piece.y, s.grid)) {
      offset = s.piece.x > BOARD_WIDTH / 2 ? -1 : 1;

      if (checkCollision(rotatedShape, s.piece.x + offset, s.piece.y, s.grid)) {
         offset = -offset;
         if (checkCollision(rotatedShape, s.piece.x + offset, s.piece.y, s.grid)) {
            offset = offset > 0 ? 2 : -2;
             if (checkCollision(rotatedShape, s.piece.x + offset, s.piece.y, s.grid)) {
                 return; 
             }
         }
      }
    }

    s.piece = { ...s.piece, shape: rotatedShape, x: s.piece.x + offset };
    setPiece({...s.piece}); 
  }, []);

  const drop = useCallback(() => {
    move(0, 1);
  }, [move]);

  const hardDrop = useCallback(() => {
    const s = stateRef.current;
    if (!s.piece || s.gameOver || s.isPaused || !s.isPlaying) return;

    let tempY = s.piece.y;
    while (!checkCollision(s.piece.shape, s.piece.x, tempY + 1, s.grid)) {
      tempY++;
    }

    s.piece.y = tempY;
    setPiece({...s.piece}); 
    lockPiece();

  }, [lockPiece]);

  useEffect(() => {
    const loop = (time: number) => {
      if (!lastTimeRef.current) lastTimeRef.current = time;
      const deltaTime = time - lastTimeRef.current;
      lastTimeRef.current = time;

      const s = stateRef.current;

      if (s.isPlaying && !s.isPaused && !s.gameOver) {
        dropCounterRef.current += deltaTime;

        // Calculate speed
        const currentSpeed = Math.max(MIN_SPEED, INITIAL_SPEED - (s.level - 1) * SPEED_DECREMENT);

        // Update speed ratio for UI
        const ratio = Math.min(1, Math.max(0, (INITIAL_SPEED - currentSpeed) / (INITIAL_SPEED - MIN_SPEED)));
        // We defer this state update to avoid heavy rerenders every frame
        // Only update if it changed significantly, or do it outside the loop if possible
        // For smoothness, we can check inside the component, but here we set it.
        // Actually, let's just use s.level for the ratio calc in the loop to minimize setState calls

        if (dropCounterRef.current > currentSpeed) {
          drop(); 
          dropCounterRef.current = 0;
        }
      }
      requestRef.current = requestAnimationFrame(loop);
    };

    requestRef.current = requestAnimationFrame(loop);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [drop]);

  // Sync speed ratio state separately when level changes
  useEffect(() => {
      const currentSpeed = Math.max(MIN_SPEED, INITIAL_SPEED - (level - 1) * SPEED_DECREMENT);
      const ratio = Math.min(1, Math.max(0, (INITIAL_SPEED - currentSpeed) / (INITIAL_SPEED - MIN_SPEED)));
      setSpeedRatio(ratio);
  }, [level]);

  const togglePause = useCallback(() => {
      if (!stateRef.current.isPlaying || stateRef.current.gameOver) return;
      const newVal = !stateRef.current.isPaused;
      stateRef.current.isPaused = newVal;
      setIsPaused(newVal);
  }, []);

  const startGame = useCallback(() => {
     stateRef.current = {
        grid: createEmptyGrid(),
        piece: null,
        nextPieceType: getRandomTetromino().type,
        score: 0,
        lines: 0,
        level: 1,
        gameOver: false,
        isPaused: false,
        isPlaying: true
     };
     setGrid(stateRef.current.grid);
     setScore(0);
     setLines(0);
     setLevel(1);
     setSpeedRatio(0);
     setGameOver(false);
     setPiece(null);
     setIsPaused(false);
     setIsPlaying(true);
     setNextPieceType(stateRef.current.nextPieceType);
     spawnPiece();
     setPopups([]);
     comboRef.current = 0;
  }, [spawnPiece]);

  const quitGame = useCallback(() => {
      stateRef.current.isPlaying = false;
      stateRef.current.isPaused = false;
      setIsPlaying(false);
      setIsPaused(false);
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (stateRef.current.gameOver || !stateRef.current.isPlaying) return;

      if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key)) {
          e.preventDefault();
      }

      switch (e.key) {
        case 'ArrowLeft': case 'a': case 'A': move(-1, 0); break;
        case 'ArrowRight': case 'd': case 'D': move(1, 0); break;
        case 'ArrowDown': case 's': case 'S': move(0, 1); break;
        case 'ArrowUp': case 'w': case 'W': case 'e': case 'E': rotate(1); break;
        case 'q': case 'Q': case 'z': case 'Z': case 'Control': rotate(-1); break;
        case ' ': hardDrop(); break;
        case 'p': case 'P': case 'Escape': togglePause(); break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [move, rotate, hardDrop, togglePause]);

  return {
    grid,
    piece,
    score,
    lines,
    level,
    gameOver,
    isPaused,
    isPlaying,
    isShaking,
    nextPieceType,
    popups,
    highScores,
    speedRatio,
    startGame,
    quitGame,
    setIsPaused: togglePause
  };
};

import React, { useRef, useEffect } from 'react';

interface P5BackgroundProps {
    intensity?: number; // 0 to 1
}

const P5Background: React.FC<P5BackgroundProps> = ({ intensity = 0 }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = window.innerWidth;
    let height = window.innerHeight;

    const resize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width;
      canvas.height = height;
    };
    window.addEventListener('resize', resize);
    resize();

    interface Shape {
        x: number;
        y: number;
        size: number;
        baseSpeedX: number;
        baseSpeedY: number;
        rotation: number;
        baseRotSpeed: number;
        color: string;
        type: 'star' | 'triangle' | 'shard';
    }

    const shapes: Shape[] = [];
    const colors = ['#ff2a6d', '#05d9e8', '#d300c5', '#304ffe', '#ffffff'];

    const createShape = (): Shape => ({
      x: Math.random() * width,
      y: Math.random() * height,
      size: Math.random() * 40 + 10,
      baseSpeedX: (Math.random() - 0.5) * 0.8,
      baseSpeedY: (Math.random() - 0.5) * 0.8,
      rotation: Math.random() * 360,
      baseRotSpeed: (Math.random() - 0.5) * 1.5,
      color: colors[Math.floor(Math.random() * colors.length)],
      type: Math.random() > 0.6 ? 'star' : (Math.random() > 0.3 ? 'triangle' : 'shard')
    });

    for (let i = 0; i < 35; i++) {
      shapes.push(createShape());
    }

    const drawStar = (cx: number, cy: number, spikes: number, outerRadius: number, innerRadius: number) => {
        let rot = Math.PI / 2 * 3;
        let x = cx;
        let y = cy;
        let step = Math.PI / spikes;

        ctx.beginPath();
        ctx.moveTo(cx, cy - outerRadius);
        for (let i = 0; i < spikes; i++) {
            x = cx + Math.cos(rot) * outerRadius;
            y = cy + Math.sin(rot) * outerRadius;
            ctx.lineTo(x, y);
            rot += step;

            x = cx + Math.cos(rot) * innerRadius;
            y = cy + Math.sin(rot) * innerRadius;
            ctx.lineTo(x, y);
            rot += step;
        }
        ctx.lineTo(cx, cy - outerRadius);
        ctx.closePath();
    }

    const animate = () => {
      // Speed multiplier based on intensity (level)
      // Base is 1, max is 3x speed at max intensity
      const speedMult = 1 + (intensity * 3);

      ctx.fillStyle = '#050510'; 
      ctx.fillRect(0, 0, width, height);

      shapes.forEach(p => {
        p.x += p.baseSpeedX * speedMult;
        p.y += p.baseSpeedY * speedMult;
        p.rotation += p.baseRotSpeed * speedMult;

        if (p.x < -100) p.x = width + 100;
        if (p.x > width + 100) p.x = -100;
        if (p.y < -100) p.y = height + 100;
        if (p.y > height + 100) p.y = -100;

        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate((p.rotation * Math.PI) / 180);

        ctx.fillStyle = p.color;
        // Make shadows more intense with speed
        ctx.shadowBlur = 15 + (intensity * 20);
        ctx.shadowColor = p.color;

        ctx.beginPath();
        if (p.type === 'triangle') {
            ctx.moveTo(0, -p.size);
            ctx.lineTo(p.size, p.size);
            ctx.lineTo(-p.size, p.size);
        } else if (p.type === 'shard') {
            ctx.moveTo(-p.size/2, -p.size);
            ctx.lineTo(p.size/2, -p.size/2);
            ctx.lineTo(0, p.size);
            ctx.lineTo(-p.size, 0);
        } else {
            drawStar(0, 0, 5, p.size, p.size/2);
        }
        ctx.fill();
        ctx.restore();
      });

      animationFrameId = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animationFrameId);
    };
  }, [intensity]);

  return <canvas ref={canvasRef} className="fixed inset-0 z-0 pointer-events-none" />;
};

export default P5Background;

