import React, { useMemo } from 'react';
import { BoardGrid, TetrominoType, Popup } from '../types';

interface BoardProps {
  grid: BoardGrid;
  piece: {
    type: TetrominoType;
    shape: number[][];
    x: number;
    y: number;
    color: string;
  } | null;
  isShaking: boolean;
  popups: Popup[];
}

const Board: React.FC<BoardProps> = ({ grid, piece, isShaking, popups }) => {

  const { displayGrid } = useMemo(() => {
    const displayGrid = grid.map(row => row.map(cell => ({ ...cell, isGhost: false })));
    let ghostY = -1;

    if (piece) {
        const shape = piece.shape;
        let tempY = piece.y;

        const check = (offY: number) => {
             for(let r=0; r<shape.length; r++) {
                 for(let c=0; c<shape[r].length; c++) {
                     if(shape[r][c]) {
                         const ny = tempY + offY + r;
                         const nx = piece.x + c;
                         if (ny >= 20 || (ny >= 0 && grid[ny][nx].locked)) return true;
                     }
                 }
             }
             return false;
        }

        while(!check(1)) {
            tempY++;
        }
        ghostY = tempY;

        if (ghostY > piece.y) {
            shape.forEach((row, r) => {
                row.forEach((value, c) => {
                    if (value) {
                        const gy = ghostY + r;
                        const gx = piece.x + c;
                        if (gy >= 0 && gy < 20 && !displayGrid[gy][gx].value) {
                            displayGrid[gy][gx] = { 
                                value: piece.type, 
                                locked: false, 
                                color: piece.color,
                                isGhost: true
                            };
                        }
                    }
                });
            });
        }

        piece.shape.forEach((row, r) => {
            row.forEach((value, c) => {
                if (value !== 0) {
                    const y = piece.y + r;
                    const x = piece.x + c;
                    if (y >= 0 && y < displayGrid.length && x >= 0 && x < displayGrid[0].length) {
                        displayGrid[y][x] = { 
                            value: piece.type, 
                            locked: false, 
                            color: piece.color,
                            isGhost: false
                        };
                    }
                }
            });
        });
    }
    return { displayGrid };
  }, [grid, piece]);

  return (
    <div className={`relative mx-auto transition-transform ${isShaking ? 'animate-shake' : ''}`}>
        <div className="absolute -inset-6 bg-gradient-to-tr from-p5-purple to-p5-blue transform rotate-1 skew-x-2 opacity-50 z-0 blur-2xl transition-opacity duration-300" style={{ opacity: isShaking ? 0.9 : 0.4 }} />
        <div className="absolute -inset-3 bg-black transform -rotate-1 z-0 border-4 border-p5-blue shadow-hard-black" />

        <div className="relative z-10 bg-[#0a0a1f] w-[85vw] max-w-[450px] aspect-[10/20] h-[80vh] sm:h-[85vh] overflow-hidden shadow-hard-black border-2 border-white/20">

            <div className="absolute inset-0 z-20 pointer-events-none scanlines opacity-30" />

            <div className="grid grid-rows-[repeat(20,minmax(0,1fr))] h-full w-full relative z-10 p-1 gap-[1px] bg-black/40">
                {displayGrid.map((row, y) => 
                    <div key={y} className="grid grid-cols-[repeat(10,minmax(0,1fr))] gap-[1px]">
                        {row.map((cell, x) => (
                            <div 
                                key={`${x}-${y}`} 
                                className={`relative w-full h-full transition-all duration-75 overflow-hidden`}
                            >
                                {cell.value && !cell.isGhost && (
                                    <div 
                                        className={`w-full h-full animate-in zoom-in duration-100 relative ${isShaking ? 'animate-flash-row' : ''}`}
                                        style={{ 
                                            backgroundColor: cell.color,
                                            border: '2px solid rgba(255,255,255,0.8)',
                                            boxShadow: `0 0 15px ${cell.color}`
                                        }}
                                    >
                                        <div className="absolute top-0 left-0 w-full h-1/2 bg-gradient-to-b from-white/40 to-transparent" />
                                    </div>
                                )}

                                {cell.isGhost && (
                                    <div 
                                        className="w-full h-full border-2 opacity-30 flex items-center justify-center bg-transparent"
                                        style={{ 
                                            borderColor: cell.color,
                                            boxShadow: `inset 0 0 5px ${cell.color}`
                                        }}
                                    />
                                )}
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {popups.map(popup => (
                <div 
                    key={popup.id}
                    className="absolute z-50 pointer-events-none animate-popup whitespace-nowrap"
                    style={{
                        left: `${Math.min(Math.max(popup.x * 10, 10), 80)}%`,
                        top: `${popup.y * 5}%`,
                    }}
                >
                    <span 
                        className="font-p5-display text-6xl text-white italic tracking-tighter drop-shadow-[4px_4px_0_rgba(0,0,0,1)] text-outline"
                        style={{ color: popup.color, textShadow: `3px 3px 0px #000, 0 0 20px ${popup.color}` }}
                    >
                        {popup.text}
                    </span>
                </div>
            ))}
        </div>

        <div className="absolute -bottom-8 -left-8 bg-black text-white font-p5-display text-4xl px-6 py-2 transform rotate-3 border-2 border-p5-cyan z-20 shadow-neon-cyan">
            <span className="text-glitch tracking-widest text-p5-cyan" data-text="ACTIVE">ACTIVE</span>
        </div>
    </div>
  );
};

export default Board;

import React, { useState, useCallback, useEffect } from 'react';
import { useTetris } from './hooks/useTetris';
import Board from './components/Board';
import { ScoreBoard, NextPiece, MenuButton, Modal } from './components/P5UI';
import P5Background from './components/P5Background';
import MainMenu from './components/MainMenu';
import TransitionOverlay, { TransitionStage } from './components/TransitionOverlay';
import IntroSequence from './components/IntroSequence';
import PauseMenu from './components/PauseMenu';
import { Settings } from './types';
import { TRANSLATIONS } from './constants';
import { Volume2, VolumeX } from 'lucide-react';

const App: React.FC = () => {
  const {
    grid,
    piece,
    score,
    lines,
    level,
    gameOver,
    isPaused,
    isPlaying,
    isShaking,
    nextPieceType,
    popups,
    highScores,
    speedRatio,
    startGame,
    quitGame,
    setIsPaused
  } = useTetris();

  const [settings, setSettings] = useState<Settings>({
      soundVolume: 50,
      language: 'en'
  });

  const t = TRANSLATIONS[settings.language];
  const [transitionStage, setTransitionStage] = useState<TransitionStage>('idle');
  const [showGame, setShowGame] = useState(false);
  const [isMenuExiting, setIsMenuExiting] = useState(false);
  const [introComplete, setIntroComplete] = useState(false);

  // Highest score from storage
  const bestScore = highScores.length > 0 ? highScores[0].score : 0;

  const handleStart = useCallback(() => {
      setIsMenuExiting(true); 
      setTimeout(() => {
          setTransitionStage('in'); 
          setTimeout(() => {
              setShowGame(true);
              startGame();
              setTransitionStage('out'); 
              setTimeout(() => {
                  setTransitionStage('idle');
                  setIsMenuExiting(false);
              }, 700); 
          }, 1000); 
      }, 500); 
  }, [startGame]);

  const handleQuit = useCallback(() => {
      setTransitionStage('in');
      setTimeout(() => {
        quitGame();
        setShowGame(false);
        setTransitionStage('out');
        setTimeout(() => setTransitionStage('idle'), 700);
      }, 1000);
  }, [quitGame]);

  // Quick mute toggle for game UI
  const toggleMute = () => {
      setSettings(s => ({ ...s, soundVolume: s.soundVolume > 0 ? 0 : 50 }));
  };

  return (
    <div className="relative min-h-screen w-full overflow-hidden font-p5-ui select-none bg-[#050510]">
      {/* Dynamic Background Intensity based on Speed/Level */}
      <P5Background intensity={speedRatio} />

      {!introComplete && <IntroSequence onComplete={() => setIntroComplete(true)} />}

      <TransitionOverlay stage={transitionStage} language={settings.language} />

      <div className={`transition-opacity duration-1000 ${introComplete ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
        {!showGame ? (
            <MainMenu 
                onStart={handleStart} 
                settings={settings}
                onUpdateSettings={setSettings}
                isExiting={isMenuExiting}
                highScores={highScores}
            />
        ) : (
            <div className="relative z-10 w-full h-screen grid grid-cols-1 lg:grid-cols-[1fr_auto_1fr] gap-0 items-center justify-items-center perspective-1000">

              {/* Left Column: Stats */}
              <div className={`
                    hidden lg:flex flex-col items-end justify-center h-full w-full pr-16 space-y-16 relative z-20 
                    transition-all duration-700 ease-out-expo origin-right
                    ${isPaused && !gameOver ? '-translate-x-[100vw] rotate-[-5deg] opacity-0' : 'translate-x-0 rotate-0 opacity-100 animate-slam-in'}
              `}>
                  <div className="relative group cursor-default transform scale-75 origin-right animate-float-glitch">
                      <div className="bg-p5-dark text-white font-p5-display text-6xl px-6 py-3 border-4 border-white shadow-neon-pink relative z-10">
                          NEON<span className="text-p5-red">BLOCKS</span>
                      </div>
                  </div>
                  <ScoreBoard score={score} level={level} lines={lines} speedRatio={speedRatio} highScore={bestScore} />
              </div>

              {/* Center: The Board */}
              <div className={`
                    relative flex items-center justify-center h-full py-4 lg:py-8 z-10 
                    transition-all duration-700 ease-out-expo
                    ${isPaused && !gameOver ? 'scale-75 opacity-20 blur-sm brightness-50 translate-y-10' : 'scale-100 opacity-100 animate-slam-in'}
              `}>
                  <Board 
                    grid={grid} 
                    piece={piece} 
                    isShaking={isShaking} 
                    popups={popups} 
                  />
              </div>

              {/* Right Column: Next & Controls */}
              <div className={`
                    hidden lg:flex flex-col items-start justify-center h-full w-full pl-16 space-y-12 relative z-20 
                    transition-all duration-700 ease-out-expo origin-left
                    ${isPaused && !gameOver ? 'translate-x-[100vw] rotate-[5deg] opacity-0' : 'translate-x-0 rotate-0 opacity-100 animate-slam-in'}
              `}>
                  <NextPiece type={nextPieceType} />
                  <div className="flex flex-col gap-6 w-full max-w-[280px]">
                      <MenuButton label={isPaused ? t.resume : t.paused} onClick={() => setIsPaused()} active={!gameOver} primary />
                      <div className="flex gap-4 w-full">
                            <button onClick={toggleMute} className="flex-1 bg-p5-dark text-white p-4 border-2 border-p5-cyan hover:bg-p5-cyan hover:text-black transition-all transform hover:rotate-3 shadow-neon-cyan flex items-center justify-center">
                              {settings.soundVolume > 0 ? <Volume2 size={28} /> : <VolumeX size={28} />}
                            </button>
                            <button onClick={handleQuit} className="flex-1 bg-p5-dark text-p5-red p-4 border-2 border-p5-red hover:bg-p5-red hover:text-white transition-all transform hover:-rotate-3 shadow-neon-pink font-bold flex items-center justify-center uppercase tracking-widest">{t.quit}</button>
                      </div>
                  </div>
              </div>

              {isPaused && !gameOver && (
                  <div className="absolute inset-0 z-50 flex items-center justify-center">
                    <PauseMenu onResume={() => setIsPaused()} onQuit={handleQuit} />
                  </div>
              )}
            </div>
        )}
      </div>

      <Modal title={t.gameOver} isOpen={gameOver}>
          <div className="flex flex-col gap-8 items-center">
              <div className="text-4xl font-black bg-white text-black px-6 py-2 transform -skew-x-12 inline-block border-2 border-p5-dark shadow-hard-black">
                {t.score}: {score.toLocaleString()}
              </div>
              <div className="w-full h-px bg-white/30" />
              <div className="flex flex-col w-full gap-4">
                  <MenuButton label={t.retry} onClick={handleStart} primary />
                  <button onClick={handleQuit} className="text-white/70 hover:text-white underline underline-offset-4 decoration-p5-red decoration-2 uppercase tracking-widest font-bold">
                      {t.back}
                  </button>
              </div>
          </div>
      </Modal>
    </div>
  );
};

export default App;

